select public.svc_sync_tenant('{"slug":"denner-detailing","name":"Denner Detailing","shortName":"Denner","kind":"detailing","tagline":"Renovace laku, keramická ochrana laku a čištění interiéru v Brně-Židenicích","description":"Vracíme vozům původní lesk a chráníme ho na dlouhá léta. Každému vozu věnuji maximální péči a používám pouze ty nejkvalitnější produkty a certifikované postupy. Přes 28 let praxe, více než 1000 vozů ročně a přes 55 recenzí na Googlu. Ceny jsou orientační – odvíjí se od velikosti vozu a míry poškození laku, konečnou cenu potvrdím po bezplatné prohlídce.","locale":"cs-CZ","timezone":"Europe/Prague","currency":"CZK","accentColor":"#F8D0B3","contacts":{"phone":"+420732461496","address":"Vančurova 4302/34, 615 00 Brno-Židenice","mapUrl":"https://www.google.com/maps/search/?api=1&query=Van%C4%8Durova%204302%2F34%2C%20615%2000%20Brno","facebook":"petr.denner.1","email":"petrdenner@seznam.cz"},"images":{"hero":"/s/denner-detailing/media/hero.webp","logo":"/s/denner-detailing/media/logo.png"},"hours":{"mon":[["08:00","20:00"]],"tue":[["08:00","20:00"]],"wed":[["08:00","20:00"]],"thu":[["08:00","20:00"]],"fri":[["08:00","20:00"]],"sat":[["08:00","20:00"]],"sun":[]},"closedDates":["2026-10-28","2026-11-17","2026-12-24","2026-12-25","2026-12-26","2027-01-01","2027-03-26","2027-03-29","2027-05-01","2027-05-08","2027-07-05","2027-07-06","2027-09-28","2027-10-28","2027-11-17","2027-12-24","2027-12-25","2027-12-26"],"booking":{"slotStepMinutes":30,"minLeadMinutes":720,"horizonDays":60,"cancelCutoffHours":24,"defaultBufferMinutes":30},"resources":[{"key":"box-1","name":"Box 1"},{"key":"box-2","name":"Box 2"}],"services":[{"key":"myti","name":"Ruční mytí","description":"Mytí laku, skel a kol dvousložkovými čističi, odmaštění mytých ploch, vysušení laku a skel. 800–1 200 Kč podle velikosti vozu.","category":"Renovace laku","price":800,"priceFrom":true,"durationMinutes":120,"resources":["box-1","box-2"]},{"key":"lesteni","name":"Leštění – obnova lesku a ochrany l