select public.svc_sync_tenant('{"slug":"graphite","name":"GRAPHITE Detailing","shortName":"GRAPHITE","kind":"detailing","tagline":"Детейлинг-студия премиум-класса","description":"Бережно моем, полируем и защищаем автомобили. Три бокса, профессиональная химия, фотоотчёт по каждой машине и гарантия на керамику и плёнку.","locale":"ru-RU","timezone":"Europe/Moscow","currency":"RUB","accentColor":"#4690FF","contacts":{"phone":"+74950001234","address":"Москва, Графитовый проезд, 7 (демо-адрес)","mapUrl":"https://yandex.ru/maps/?text=%D0%9C%D0%BE%D1%81%D0%BA%D0%B2%D0%B0","lat":55.7558,"lng":37.6173,"telegram":"graphite_detailing_demo"},"images":{"hero":"/s/graphite/media/hero.webp","logo":"/s/graphite/media/logo.png"},"hours":{"mon":[["09:00","21:00"]],"tue":[["09:00","21:00"]],"wed":[["09:00","21:00"]],"thu":[["09:00","21:00"]],"fri":[["09:00","21:00"]],"sat":[["10:00","20:00"]],"sun":[["10:00","18:00"]]},"closedDates":["2026-12-31","2027-01-01","2027-01-02"],"booking":{"slotStepMinutes":30,"minLeadMinutes":120,"horizonDays":30,"cancelCutoffHours":12,"defaultBufferMinutes":30},"resources":[{"key":"wash","name":"Моечный бокс"},{"key":"detail-1","name":"Бокс детейлинга 1"},{"key":"detail-2","name":"Бокс детейлинга 2"}],"services":[{"key":"detail-wash","name":"Детейлинг-мойка","description":"Двухфазная мойка, очистка дисков и арок, сушка, обработка резины.","category":"Мойка","price":3500,"priceFrom":false,"durationMinutes":120,"bufferMinutes":15,"resources":["wash","detail-1","detail-2"]},{"key":"headlights","name":"Полировка фар","description":"Восстановление прозрачности и защитный состав. Обе фары.","category":"Полировка","price":3000,"priceFrom":false,"durationMinutes":90,"resources":["detail-1","detail-2"]},{"key":"interior","name":"Химчистка салона","description":"Сиденья, потолок, ковры, пластик и кожа. Сушка и кондиционер для кожи.","category":"Салон","price":12000,"priceFrom":false,"durationMinutes":360,"resources":["detail-1","detail-2"]},{"key":"polish","name":"Полировка кузова","description":"Абразивная полировка в два этапа: убираем голограммы и мелкие царапины.","category":"Полировка","price":18000,"priceFrom":true,"durationMinutes":480,"resources":["detail-1","detail-2"]},{"key":"ceramic","name":"Керамическое покрытие","description":"Подготовка, полировка и керамика в 2 слоя. Машина остаётся в боксе на 2 дня.","category":"Защита","price":45000,"priceFrom":true,"durationMinutes":1980,"bufferMinutes":60,"resources":["detail-1","detail-2"]},{"key":"ppf-front","name":"Плёнка на зону риска","description":"Антигравийная полиуретановая плёнка: капот, бампер, фары, зеркала. 2 дня в боксе.","category":"Защита","price":65000,"priceFrom":true,"durationMinutes":2880,"bufferMinutes":60,"resources":["detail-2"]}],"infoCards":[{"icon":"shield","title":"Гарантия","text":"До 3 лет на керамику и до 5 лет на плёнку — с паспортом работ."},{"icon":"sparkle","title":"Фотоотчёт","text":"Присылаем фото до и после, чтобы вы видели каждый этап."},{"icon":"coffee","title":"Зона ожидания","text":"Кофе, Wi‑Fi и окно в бокс — можно смотреть, как работаем."}],"gallery":[{"image":"/s/graphite/media/work-1.webp","caption":"Керамика в 2 слоя, Porsche Taycan"},{"image":"/s/graphite/media/work-2.webp","caption":"Полировка кузова, BMW 5 серии"},{"image":"/s/graphite/media/work-3.webp","caption":"Химчистка салона, Mercedes GLE"},{"image":"/s/graphite/media/work-4.webp","caption":"Плёнка на зону риска, Audi Q8"},{"image":"/s/graphite/media/work-5.webp","caption":"Детейлинг-мойка, Range Rover"}],"faq":[],"owner":{"email":"owner@graphite.demo"},"assistant":{"enabled":true}}'::jsonb, '30ef17c6f34bc1e1a8ff7eaee6687921f69f042b7a123af0be7e906b4b145ee5', true);
