select public.svc_sync_tenant('{"slug":"h-pure","name":"H-Pure","shortName":"H-Pure","kind":"detailing","tagline":"Mobilní čištění a detailing vozidel v Ostravě – přijedeme k vám","description":"Specialisté na mobilní čištění a detailing vozidel, čištění koberců a sedacích souprav. Také máte rádi příjemné svezení v čistém, voňavém a naleštěném autě? Nebo se chystáte prodat vůz a chcete zvýšit jeho cenu? Dokonalý detailing, oprava drobných oděrek a škrábanců na laku, provoněný interiér, ošetření a výživa kůže, oživení plastů a mnoho dalšího. Jsme pojištěni u Kooperativy, včetně převzatých motorových vozidel.","locale":"cs-CZ","timezone":"Europe/Prague","currency":"CZK","accentColor":"#F5B301","contacts":{"phone":"+420737805029","address":"Za Školou 2839/8, 700 30 Ostrava-Zábřeh","legalAddress":"Jan Hrbáček, Za Školou 2839/8, 700 30 Ostrava-Zábřeh, IČO 74722344","mapUrl":"https://www.google.com/maps/search/?api=1&query=Za%20%C5%A0kolou%202839%2F8%2C%20700%2030%20Ostrava","instagram":"hpure.cz","facebook":"https://www.facebook.com/profile.php?id=100087584511870","email":"h-pure@email.cz"},"images":{"hero":"/s/h-pure/media/hero.webp","logo":"/s/h-pure/media/logo.png"},"hours":{"mon":[["08:00","18:00"]],"tue":[["08:00","18:00"]],"wed":[["08:00","18:00"]],"thu":[["08:00","18:00"]],"fri":[["08:00","18:00"]],"sat":[],"sun":[]},"closedDates":["2026-10-28","2026-11-17","2026-12-24","2026-12-25","2026-12-26","2027-01-01","2027-03-26","2027-03-29","2027-05-01","2027-05-08","2027-07-05","2027-07-06","2027-09-28","2027-10-28","2027-11-17","2027-12-24","2027-12-25","2027-12-26"],"booking":{"slotStepMinutes":30,"minLeadMinutes":180,"horizonDays":45,"cancelCutoffHours":24,"defaultBufferMinutes":30},"resources":[{"key":"tym","name":"Mobilní tým"}],"services":[{"key":"zakladni","name":"Interiér – Základní Packet","description":"Cca 1,5 hod. Důkladné vysátí celého interiéru včetně kufru, umytí a chemické ošetření plastů včetně impregnace, vyčištění oken z obou stran včetně zrcátek. Ceny jsou orientační – odvíjí se od míry znečištění a velikosti vozidla.","category":"Čištění vozidel","price":2100,"priceFrom":true,"durationMinutes":90,"resources":["tym"]},{"key":"medium","name":"Interiér – Medium Packet","description":"Cca 3–4 hod. Vše ze Základního packetu plus mokré čištění sedaček a koberečků (tepování 1 sady koberečků) a čištění a impregnace kožených či alcantara sedaček. Ceny jsou orientační – odvíjí se od míry znečištění a velikosti vozidla.","category":"Čištění vozidel","price":2800,"priceFrom":true,"durationMinutes":240,"resources":["tym"]},{"key":"full","name":"Full Detail Packet","description":"Cca 5–7 hod. Bezkontaktní mytí, aktivní pěna, vysušení, mezidveřní prostory, motorový prostor, kompletní interiér s tepováním, výživa a impregnace sedaček Gyeon Q2, dekontaminace kol a UV ochrana pneu. Ceny jsou orientační – odvíjí se od míry znečištění a velikosti vozidla.","category":"Čištění vozidel","price":4000,"priceFrom":true,"durationMinutes":420,"resources":["tym"]},{"key":"exterier-plus","name":"Exteriér plus","description":"Doplněk k Základnímu packetu: oplach vysokotlakým čističem, aktivní pěna, ruční mytí karoserie mycími rukavicemi, dekontaminace kol a UV ochrana pneumatik.","category":"Čištění vozidel","price":1800,"priceFrom":false,"durationMinutes":60,"resources":["tym"]},{"key":"koberecky","name":"Tepování koberečků (za kus)","description":"Tepování koberečků mokrou cestou – 100 Kč za kus.","category":"Doplňkové služby","price":100,"priceFrom":false,"durationMinutes":15,"resources":["tym"]},{"key":"kufr","name":"Tepování kufru","description":"Tepování zavazadlového prostoru.","category":"Doplňkové služby","price":400,"priceFrom":false,"durationMinutes":30,"resources":["tym"]},{"key":"stropnice","name":"Vyčištění stropnice","description":"Šetrné vyčištění stropnice.","category":"Doplňkové služby","price":350,"priceFrom":false,"durationMinutes":45,"resources":["tym"]},{"key":"rezerva","name":"Vyčištění prostoru pod rezervou","description":"Vyčištění úložného prostoru pod rezervou.","category":"Doplňkové služby","price":200,"priceFrom":false,"durationMinutes":15,"resources":["tym"]},{"key":"ozon","name":"Dezinfekce klimatizace ozónem / aerosolem","description":"Dezinfekce klimatizace ozónem nebo aerosolem – 400 až 500 Kč.","category":"Doplňkové služby","price":400,"priceFrom":true,"durationMinutes":30,"resources":["tym"]},{"key":"clay","name":"Dekontaminace laku metodou CLAY","description":"Chemická a mechanická dekontaminace laku – vhodné před aplikací vosku.","category":"Doplňkové služby","price":400,"priceFrom":false,"durationMinutes":60,"resources":["tym"]},{"key":"vosk-tekuty","name":"Aplikace tekutého vosku","description":"Aplikace tekutého vosku a závěrečné ošetření Auto Finesse Finale pro prohloubení lesku.","category":"Doplňkové služby","price":500,"priceFrom":false,"durationMinutes":30,"resources":["tym"]},{"key":"vosk-tuhy","name":"Aplikace tuhého vosku","description":"Dekontaminace, polish, odmaštění a aplikace tuhého vosku s delší životností než tekutý. 1 000–1 200 Kč dle velikosti vozu – dejte nám prosím vědět předem.","category":"Doplňkové služby","price":1000,"priceFrom":true,"durationMinutes":120,"resources":["tym"]},{"key":"lesteni","name":"Renovace laku – rozleštění celého vozu","description":"Rozleštění poškozeného laku celého vozu. Lokální rozleštění (kliky, oděrky, povrchové škrábance) naceníme podle počtu a velikosti míst.","category":"Doplňkové služby","price":6000,"priceFrom":true,"durationMinutes":480,"resources":["tym"]},{"key":"polepy","name":"Šetrné odstranění polepů, fólií a nálepek","description":"Odstranění polepů, fólií a nálepek z karoserie přípravky Koch-Chemie, včetně zbytků lepidel, polétavé rzi a asfaltu, s možností lokálního rozleštění. Cena po osobní prohlídce vozu.","category":"Kamiony a firmy","price":0,"priceFrom":false,"durationMinutes":240,"resources":["tym"]},{"key":"kamion","name":"Interiér kamionu (tahače) – Medium Detail","description":"Detailní čištění interiéru tahače, cena bez dopravy. Nadměrné znečištění (psí chlupy, rozlité nápoje) 6 000 Kč, extrémní (kuřák, mastnota z vaření) 8 000 Kč. Při rámcové smlouvě množstevní sleva.","category":"Kamiony a firmy","price":4000,"priceFrom":true,"durationMinutes":300,"resources":["tym"]},{"key":"koberec","name":"Čištění koberce do 2 m²","description":"Suché i mokré čištění. Koberec s krátkým vlasem od 600 Kč, každý další m² 60–90 Kč dle znečištění, dlouhý vlas +25 Kč/m².","category":"Koberce a sedačky","price":499,"priceFrom":true,"durationMinutes":60,"resources":["tym"]},{"key":"sedacka","name":"Čištění sedací soupravy (za sedací místo)","description":"Cena za jedno sedací místo (cca 60 cm). Polštáře malé 40 Kč, velké 60 Kč za kus.","category":"Koberce a sedačky","price":200,"priceFrom":false,"durationMinutes":30,"resources":["tym"]},{"key":"matrace","name":"Čištění matrace","description":"Matrace 180×80 cm z obou stran – 500 Kč za kus.","category":"Koberce a sedačky","price":500,"priceFrom":false,"durationMinutes":45,"resources":["tym"]},{"key":"kreslo","name":"Čištění křesla","description":"Křeslo 199 Kč/ks, taburet 130 Kč/ks, kuchyňská lavice 350 Kč/ks, židle 60–90 Kč/ks.","category":"Koberce a sedačky","price":199,"priceFrom":false,"durationMinutes":30,"resources":["tym"]}],"infoCards":[{"icon":"car","title":"Přijedeme k vám","text":"Mobilní čištění – doprava do 10 km zdarma, v Moravskoslezském kraji 10 Kč/km."},{"icon":"shield","title":"Pojištění Kooperativa","text":"Jsme pojištěni pro případ škody na majetku, včetně převzatých motorových vozidel."},{"icon":"wrench","title":"Spolupráce s firmami","text":"Celoroční servis a čištění firemních vozů – spolupracujeme s desítkami firem."}],"gallery":[{"image":"/s/h-pure/media/work-cupra.webp","caption":"Cupra"},{"image":"/s/h-pure/media/work-yaris.webp","caption":"Toyota Yaris"},{"image":"/s/h-pure/media/work-vosk.webp","caption":"Ruční aplikace vosku"},{"image":"/s/h-pure/media/work-interier-mercedes.webp","caption":"Čištění interiéru Mercedes-Benz"},{"image":"/s/h-pure/media/work-interier-cupra.webp","caption":"Čištění palubní desky"},{"image":"/s/h-pure/media/work-pena.webp","caption":"Mytí vozu aktivní pěnou"},{"image":"/s/h-pure/media/work-octavia-combi.webp","caption":"Škoda Octavia Combi – před a po"},{"image":"/s/h-pure/media/work-octavia.webp","caption":"Škoda Octavia – před a po"},{"image":"/s/h-pure/media/work-octavia-2.webp","caption":"Škoda Octavia II Combi – před a po"},{"image":"/s/h-pure/media/work-jaguar-interier.webp","caption":"Interiér Jaguar F-Pace – před a po"},{"image":"/s/h-pure/media/work-jaguar-motor.webp","caption":"Motorový prostor Jaguar – před a po"},{"image":"/s/h-pure/media/work-motor.webp","caption":"Motorový prostor – před a po"},{"image":"/s/h-pure/media/work-ford-interier.webp","caption":"Interiér Fordu – před a po"},{"image":"/s/h-pure/media/work-tepovani.webp","caption":"Tepování sedadel – před a po"},{"image":"/s/h-pure/media/work-kola.webp","caption":"Čištění kol – před a po"},{"image":"/s/h-pure/media/work-polep.webp","caption":"Šetrné odstranění polepu z dodávky"}],"faq":[{"question":"Přijedete za mnou?","answer":"Ano, specializujeme se na mobilní čištění. U vozidel je doprava do 10 km zdarma, mimo Ostravu v rámci Moravskoslezského kraje účtujeme 10 Kč/km. U čištění koberců a sedaček je doprava po Ostravě zdarma, mimo Ostravu příplatek 250 Kč.","keywords":["prijedete","mobilni","doprava","k nam","domu","kde","adresa","ostrav","km"]},{"question":"Liší se cena podle vozu?","answer":"Ano. Ceny se odvíjí od míry znečištění a velikosti vozidla. Za SUV, MPV a silně znečištěná vozidla (např. firemní auta ze stavebnictví a průmyslu) nebo při nadměrném znečištění je přirážka od 25 %. Dodávky a vícemístná vozidla od 35 %.","keywords":["suv","mpv","dodavk","velikost","priraz","priplat","znecist","spinav","kolik bude"]},{"question":"Co obsahují jednotlivé packety?","answer":"Základní Packet (od 2 100 Kč, cca 1,5 hod): vysátí, plasty a okna. Medium Packet (od 2 800 Kč, cca 3–4 hod): navíc tepování sedaček a koberečků a čištění kůže/alcantary. Full Detail Packet (od 4 000 Kč, cca 5–7 hod): kompletní interiér i exteriér včetně motorového prostoru a ošetření sedaček Gyeon Q2.","keywords":["packet","paket","balicek","zakladni","medium","full","rozdil","co obsahuje"]},{"question":"Jste pojištěni?","answer":"Ano, jsme pojištěni proti vzniku škody na majetku u Kooperativy – včetně újmy na movité věci převzaté nebo užívané, tedy i převzatých motorových vozidel.","keywords":["pojist","skoda","kooperativ","odpovednost"]},{"question":"Děláte i firemní vozy a kamiony?","answer":"Ano. Firmám nabízíme dlouhodobou spolupráci a celoroční servis a čištění vozidel – spolupracujeme s desítkami firem. Interiér tahače (Medium Detail) od 4 000 Kč bez dopravy, při rámcové smlouvě s množstevní slevou.","keywords":["firm","kamion","tahac","flotil","ramcov","faktur","dodavk"]},{"question":"Čistíte i koberce a sedačky?","answer":"Ano. Koberec do 2 m² od 499 Kč, sedací souprava 200 Kč za sedací místo, matrace 500 Kč, křeslo 199 Kč. U více znečištěných ploch účtujeme příplatek 20 %. Čištění podlah, oken a žaluzií parním čističem dle dohody.","keywords":["koberec","koberc","sedack","gauc","matrac","kreslo","zidle","zaluzi"]},{"question":"Jak reklamovat čištění koberce?","answer":"Reklamaci vyčištěného koberce je nutné provést nejpozději do 24 hodin od převzetí. U vlněných koberců bílé barvy nelze zaručit bezchybné vyčištění a na koberce předávané ve stočeném stavu se záruka nevztahuje.","keywords":["reklamac","zaruk","stiznost","nespokojen"]}],"owner":{"email":"owner@example.com"},"assistant":{"enabled":true}}'::jsonb, 'f6b4d89df9b4c65fd2d8c14337408efb99f19da533c7e25ec0e5ab416d34dde9', true);
