es":180,"resources":["box-1","box-2"]},{"key":"strop","name":"Čištění stropu","description":"Vyčištění stropnice.","category":"Interiér","price":900,"priceFrom":false,"durationMinutes":60,"resources":["box-1","box-2"]},{"key":"plasty","name":"Čištění a ošetření plastů interiéru","description":"Vyčištění a ošetření plastových dílů interiéru.","category":"Interiér","price":600,"priceFrom":false,"durationMinutes":45,"resources":["box-1","box-2"]},{"key":"kuze","name":"Čištění a ošetření kožených sedadel","description":"Šetrné vyčištění a ošetření kožených sedadel.","category":"Interiér","price":1900,"priceFrom":false,"durationMinutes":120,"resources":["box-1","box-2"]},{"key":"koberecky","name":"Mytí gumových koberečků","description":"Umytí gumových koberečků.","category":"Interiér","price":200,"priceFrom":false,"durationMinutes":15,"resources":["box-1","box-2"]},{"key":"klimatizace","name":"Dezinfekce klimatizace","description":"Dezinfekce klimatizace sprejem.","category":"Interiér","price":600,"priceFrom":false,"durationMinutes":30,"resources":["box-1","box-2"]},{"key":"ozon","name":"Dezinfekce interiéru ozonem","description":"Dezinfekce interiéru a odstranění pachů ozonem.","category":"Interiér","price":1000,"priceFrom":false,"durationMinutes":60,"resources":["box-1","box-2"]},{"key":"motor","name":"Mytí a konzervace motoru","description":"Mytí a konzervace motorového prostoru (bez záruky).","category":"Motor a motocykly","price":1000,"priceFrom":false,"durationMinutes":60,"resources":["box-1","box-2"]},{"key":"moto-myti","name":"Ruční mytí motocyklu","description":"Ruční mytí motocyklu.","category":"Motor a motocykly","price":1000,"priceFrom":true,"durationMinutes":90,"resources":["box-1","box-2"]},{"key":"moto-vosk","name":"Voskování motocyklu","description":"Voskování a ochrana motocyklu.","category":"Motor a motocykly","price":1000,"priceFrom":true,"durationMinutes":90,"resources":["box-1","box-2"]}],"infoCards":[{"icon":"medal","title":"Přes 10 let na trhu","text":"Nejdéle fungující ruční mytí aut v Brně, hodnocení 4,9/5 na Googlu."},{"icon":"car","title":"Odvoz a dovoz vozu","text":"V rámci Brna a okolí vůz vyzvedneme a vrátíme umytý – od 500 Kč."},{"icon":"sparkle","title":"Značková kosmetika","text":"Meguiar''s, Auto Finesse, Autoglym, Rupes, Swissvax, Gtechniq, Gyeon a další."}],"gallery":[{"image":"/s/topmyti/media/work-bentley-gtc.webp","caption":"Bentley Continental GTC"},{"image":"/s/topmyti/media/work-bentley.webp","caption":"Bentley Continental"},{"image":"/s/topmyti/media/work-bmw-e24.webp","caption":"Klasika BMW řady 6"},{"image":"/s/topmyti/media/work-mercedes-s.webp","caption":"Mercedes-Benz třídy S"},{"image":"/s/topmyti/media/work-mustang.webp","caption":"Ford Mustang"},{"image":"/s/topmyti/media/work-harley.webp","caption":"Detailing motocyklu Harley-Davidson"},{"image":"/s/topmyti/media/work-lesteni.webp","caption":"Leštění karbonových dílů"},{"image":"/s/topmyti/media/work-tepovani.webp","caption":"Tepování koberců extraktorem"},{"image":"/s/topmyti/media/work-kuze.webp","caption":"Čištění kožených sedadel"},{"image":"/s/topmyti/media/work-motor.webp","caption":"Mytí a konzervace motoru"},{"image":"/s/topmyti/media/work-myti.webp","caption":"Ruční mytí karoserie"},{"image":"/s/topmyti/media/work-koberecky.webp","caption":"Čištění koberečků"},{"image":"/s/topmyti/media/work-cekarna.webp","caption":"Čekárna v naší provozovně"}],"faq":[{"question":"Jak k vám vjedu?","answer":"Najdete nás na ulici Hybešova 21 v centru Brna, ve dvorním traktu. Při vjezdu do dvora si u závory odeberte parkovací lístek a vjeďte dovnitř. Při odjezdu vám závoru otevřeme.","keywords":["vjedu","vjezd","zavor","parkovac","listek","kde vas najdu","najdu","adres","dvor"]},{"question":"Můžete auto vyzvednout a přivézt zpět?","answer":"Ano. Rádi vám ušetříme čas – v rámci Brna a okolí vaše vozidlo vyzvedneme a doručíme zpět umyté. Odvoz a dovoz vozidla stojí od 500 Kč.","keywords":["vyzved","odvoz","dovoz","dovez","privez","pristav"]},{"question":"Jaké jsou storno podmínky?","answer":"Při zrušení rezervace méně než 24 hodin předem účtujeme 50 % ceny objednané služby. U dražších, exkluzivních služeb požadujeme nevratnou zálohu 50 % z ceny.","keywords":["storno","zrusen","zrusit","zaloh"]},{"question":"Máte věrnostní program?","answer":"Ano, VIP karty. Stříbrná obsahuje 10 mycích programů typu A (luxování a suché čištění interiéru, ruční mytí karoserie) a slevu 10 % na všechny služby. Zlatá obsahuje 10 programů typu B (navíc čištění plastů interiéru a oken) a slevu 20 %. Po vyčerpání programů je možné kartu znovu nabít.","keywords":["vip","vernost","karta","karty","sleva","slevu","pravideln"]},{"question":"Prodáváte dárkové poukazy?","answer":"Ano, v libovolné hodnotě – s finanční částkou nebo s vybranými službami. Poukazy mají roční platnost a dostanete je ve stylové černé obálce. Koupit je můžete na recepci na Hybešově 21 nebo e-mailem na topmyticz@gmail.com.","keywords":["poukaz","darek","darkov","voucher"]},{"question":"Kolik stojí leštění laku?","answer":"Leštění (renovace laku) účtujeme 1 500 Kč za hodinu práce. Rozsah a výslednou cenu domluvíme na místě podle stavu laku.","keywords":["lesten","renovace laku","za hodinu","hodinov"]},{"question":"Ručíte za mytí motoru?","answer":"Mytí a konzervaci motoru provádíme pečlivě, podle našeho ceníku je ale tato služba bez záruky.","keywords":["motor","zaruk","ruci","ucite"]}],"owner":{"email":"owner@example.com"},"assistant":{"enabled":true}}'::jsonb, '419b268428b289117ef3e6b106a2d8a11a5a3bc4e6c72c22595ed232b655021e', true);
