select public.svc_sync_tenant('{"slug":"umyem","name":"UMYEM","shortName":"UMYEM","kind":"detailing","tagline":"Děláme krásná a voňavá auta – detailing a keramické ochrany v Brně","description":"Jsme specialisté na ošetření vozidel keramickými povlaky a vosky, renovujeme laky a oživujeme interiéry. Zabýváme se detailovou péčí o automobily od roku 2011 a ročně pečujeme o zhruba 450 aut. Naší hlavní předností je individuální přístup k zákazníkovi. Jsme certifikovaným resellerem GYEON a při renovaci laku používáme výhradně leštičky RUPES. Jsme oblíbení, jsme z Brna, jsme pozorní, jsme lidští, jsme UMYEM.","locale":"cs-CZ","timezone":"Europe/Prague","currency":"CZK","accentColor":"#2DD4BF","contacts":{"phone":"+420776170777","address":"Vranovská 53/2, 614 00 Brno-Zábrdovice (vjezd z ulice Jana Svobody)","legalAddress":"UMYEM, s.r.o., Palackého třída 249/32, 621 00 Brno, IČ 05693616","mapUrl":"https://www.google.com/maps/search/?api=1&query=Vranovsk%C3%A1%2053%2F2%2C%20614%2000%20Brno","instagram":"umyem_love_life","facebook":"umyem","email":"jirka@umyem.com"},"images":{"hero":"/s/umyem/media/hero.webp","logo":"/s/umyem/media/logo.png"},"hours":{"mon":[["08:00","15:00"]],"tue":[["08:00","15:00"]],"wed":[["08:00","15:00"]],"thu":[["08:00","15:00"]],"fri":[["08:00","15:00"]],"sat":[],"sun":[]},"closedDates":["2026-10-28","2026-11-17","2026-12-24","2026-12-25","2026-12-26","2027-01-01","2027-03-26","2027-03-29","2027-05-01","2027-05-08","2027-07-05","2027-07-06","2027-09-28","2027-10-28","2027-11-17","2027-12-24","2027-12-25","2027-12-26"],"booking":{"slotStepMinutes":30,"minLeadMinutes":240,"horizonDays":45,"cancelCutoffHours":24,"defaultBufferMinutes":15},"resources":[{"key":"box-1","name":"Box 1"},{"key":"box-2","name":"Box 2"}],"services":[{"key":"myti","name":"1. Exteriér – mytí","description":"Cca 45 minut. Šetrné mytí šamponem s odstraněním hmyzu z masky, skel a zrcátek, mytí kol a nástupních prostor, sušení ručníkem i vzduchem a impregnace pneumatik. Cena bez DPH.",